using MediatR;using OAS.Application.Accounting.Abstractions;using OAS.Contracts.Accounting.ExchangeRates;using ContractRateType=OAS.Contracts.Accounting.Enums.ExchangeRateType;using ContractSource=OAS.Contracts.Accounting.Enums.ExchangeRateSource;using DomainRateType=OAS.Domain.Accounting.Enums.ExchangeRateType;
namespace OAS.Application.Accounting.ExchangeRates.Queries.GetEffectiveExchangeRate;public sealed class GetEffectiveExchangeRateQueryHandler(IExchangeRateResolver resolver):IRequestHandler<GetEffectiveExchangeRateQuery,EffectiveExchangeRateDto>{public async Task<EffectiveExchangeRateDto> Handle(GetEffectiveExchangeRateQuery r,CancellationToken ct){var x=await resolver.ResolveAsync(r.CurrencyId,r.Date,(DomainRateType)(byte)r.RateType,null,false,ct);return new(x.CurrencyId,x.CurrencyCode,x.CurrencySymbol,x.CurrencyDecimalPlaces,x.Rate,x.RateDate,(ContractRateType)(byte)x.RateType,(ContractSource)(byte)x.Source,x.IsBaseCurrency);}}
